import{i as e,r as t,s as n,t as r}from"./app-BJYidpcE.js";var i=JSON.parse(`{"path":"/ai-framework/langchain-typescript.html","title":"LangChain.js 入门教程（TypeScript / 前端版）","lang":"en-US","frontmatter":{},"git":{"updatedTime":1785804532000,"contributors":[{"name":"vlily","username":"vlily","email":"vlily@vlilydeMacBook-Pro.local","commits":1,"url":"https://github.com/vlily"}],"changelog":[{"hash":"ddd6163bcd8435bd3ec9adfbbacac400f80f5418","time":1785804532000,"email":"vlily@vlilydeMacBook-Pro.local","author":"vlily","message":"docs(ai-framework): add LangChain.js TypeScript 与 NestJS 集成教程"}]},"filePathRelative":"ai-framework/langchain-typescript.md"}`),a={name:`langchain-typescript.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="langchain-js-入门教程-typescript-前端版" tabindex="-1"><a class="header-anchor" href="#langchain-js-入门教程-typescript-前端版"><span>LangChain.js 入门教程（TypeScript / 前端版）</span></a></h1><blockquote><p>面向 0 基础前端开发者的 LangChain 中文入门教程，全程使用 TypeScript 编写。 如果你学过上面的 <a href="./langchain">Python 版</a>，这一版会让你更容易上手——因为前端开发者天生就熟悉 JS/TS 生态。</p></blockquote><h2 id="langchain-是什么" tabindex="-1"><a class="header-anchor" href="#langchain-是什么"><span>LangChain 是什么？</span></a></h2><p>LangChain 是一个帮你更方便调用大语言模型（LLM）来开发 AI 应用的框架。它有 JavaScript / TypeScript 版本，官方叫 <strong>LangChain.js</strong>（<code>langchain</code> 包）。</p><p><strong>不用 LangChain 时，你要自己写：</strong></p><ul><li>拼接提示词</li><li>调用模型 API</li><li>解析返回结果</li><li>管理对话历史</li><li>调用外部工具</li></ul><p><strong>用 LangChain 后，这些都有现成的模块。</strong></p><p>对前端来说，LangChain 就像给 LLM 加了一层「封装库」，类似 <code>axios</code> 之于 <code>fetch</code>。</p><blockquote><p>注意：LangChain 有两个生态——Python（<code>langchain</code>）和 JS/TS（<code>langchain</code> npm 包）。本教程用 TS 生态。</p></blockquote><hr><h2 id="准备工作" tabindex="-1"><a class="header-anchor" href="#准备工作"><span>准备工作</span></a></h2><h3 id="环境要求" tabindex="-1"><a class="header-anchor" href="#环境要求"><span>环境要求</span></a></h3><ul><li>Node.js <strong>18+</strong></li><li>一个模型 API Key（本教程以 OpenAI 为例，你也可以换成 DeepSeek、通义千问等兼容接口）</li></ul><h3 id="项目初始化" tabindex="-1"><a class="header-anchor" href="#项目初始化"><span>项目初始化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">mkdir</span> langchain-demo</span>
<span class="line"><span class="token builtin class-name">cd</span> langchain-demo</span>
<span class="line"><span class="token function">npm</span> init <span class="token parameter variable">-y</span></span>
<span class="line"><span class="token function">npm</span> <span class="token function">install</span> langchain @langchain/openai dotenv</span>
<span class="line"><span class="token function">npm</span> <span class="token function">install</span> <span class="token parameter variable">-D</span> typescript tsx @types/node</span>
<span class="line">npx tsc <span class="token parameter variable">--init</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="配置环境变量" tabindex="-1"><a class="header-anchor" href="#配置环境变量"><span>配置环境变量</span></a></h3><p>创建 <code>.env</code> 文件，填入你的 API Key：</p><div class="language-env line-numbers-mode" data-highlighter="prismjs" data-ext="env"><pre><code class="language-env"><span class="line">OPENAI_API_KEY=sk-xxxxx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p>换成其他国内模型也可以，比如 DeepSeek： <code>OPENAI_API_KEY=sk-xxx</code> + <code>OPENAI_BASE_URL=https://api.deepseek.com</code></p></blockquote><p>新建 <code>index.ts</code> 测试一下：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;游戏开始！&#39;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">npx tsx index.ts</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>能输出 <code>游戏开始！</code> 就说明环境 OK 了。</p><hr><h2 id="核心概念-先有印象-不用背" tabindex="-1"><a class="header-anchor" href="#核心概念-先有印象-不用背"><span>核心概念（先有印象，不用背）</span></a></h2><table><thead><tr><th>概念</th><th>是什么</th><th>类比前端</th></tr></thead><tbody><tr><td>Model</td><td>大模型（GPT、Claude 等）</td><td>后端的 API 服务</td></tr><tr><td>Prompt</td><td>你给模型的指令</td><td>HTTP 请求的 body</td></tr><tr><td>Chain</td><td>把多个步骤串联起来</td><td>Promise.then 链 / pipe</td></tr><tr><td>Tool</td><td>模型能调用的外部功能</td><td>API 接口</td></tr><tr><td>Agent</td><td>让模型自己决定调什么工具</td><td>自动路由 / 状态机</td></tr><tr><td>Memory</td><td>让模型记住上下文</td><td>Redux / Pinia 状态</td></tr></tbody></table><p>学的时候记住一句话：<strong>LangChain 就是把 AI 开发里的重复动作变成模块化的积木。</strong></p><hr><h2 id="基础用法" tabindex="-1"><a class="header-anchor" href="#基础用法"><span>基础用法</span></a></h2><h3 id="_1-调用模型" tabindex="-1"><a class="header-anchor" href="#_1-调用模型"><span>1. 调用模型</span></a></h3><p>调用模型就像调用一个异步 API，用 <code>await</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 创建一个模型实例，就像 new Axios() 创建客户端</span></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  temperature<span class="token operator">:</span> <span class="token number">0.7</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// invoke = 一次性传入消息，返回完整回答（就像发一次 HTTP 请求）</span></span>
<span class="line"><span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> model<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token string">&#39;中国的首都是哪里？&#39;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 输出：中国的首都是北京。</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>invoke</code> 返回的是一个 <code>AIMessage</code> 对象，不是纯字符串。想要纯字符串，后面会讲「输出解析器」。</p><h3 id="_2-提示词模板-prompt-template" tabindex="-1"><a class="header-anchor" href="#_2-提示词模板-prompt-template"><span>2. 提示词模板（Prompt Template）</span></a></h3><p>把提示词里的变量抽出来，类似 JS 的模板字符串：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatPromptTemplate <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/prompts&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 定义模板，花括号里是变量</span></span>
<span class="line"><span class="token keyword">const</span> prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span><span class="token function">fromMessages</span><span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;你是一个{role}，请用{style}风格回答问题。&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;human&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;{question}&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 传入变量，生成最终消息数组</span></span>
<span class="line"><span class="token keyword">const</span> messages <span class="token operator">=</span> <span class="token keyword">await</span> prompt<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  role<span class="token operator">:</span> <span class="token string">&#39;AI 助手&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  style<span class="token operator">:</span> <span class="token string">&#39;幽默&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  question<span class="token operator">:</span> <span class="token string">&#39;什么是机器学习？&#39;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>messages<span class="token punctuation">.</span><span class="token function">toChatMessages</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ChatPromptTemplate</code> 就是「提示词的模板引擎」，和渲染字符串脚本很像。</p><h3 id="_3-chain-把-prompt-和-model-串起来" tabindex="-1"><a class="header-anchor" href="#_3-chain-把-prompt-和-model-串起来"><span>3. Chain：把 Prompt 和 Model 串起来</span></a></h3><p>这是 LangChain.js 玩法——用 <strong><code>.pipe()</code></strong> 把多个步骤串成一条链（Chain）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatPromptTemplate <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/prompts&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> StringOutputParser <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/output_parsers&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span><span class="token function">fromTemplate</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token string">&#39;把下面的句子翻译成{language}：{text}&#39;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 输出解析器：把模型返回的 Message 转成纯字符串</span></span>
<span class="line"><span class="token keyword">const</span> parser <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">StringOutputParser</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// .pipe() 类似前端的阮一峰常用工具 pipe：prompt 的输出 → model → parser</span></span>
<span class="line"><span class="token keyword">const</span> chain <span class="token operator">=</span> prompt<span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>parser<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> chain<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  language<span class="token operator">:</span> <span class="token string">&#39;英文&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  text<span class="token operator">:</span> <span class="token string">&#39;今天天气真好&#39;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 输出：The weather is really nice today.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>StringOutputParser</code> 就像给模型输出做了个 <code>.toString()</code>，让你直接拿字符串。</p><h3 id="_4-输出解析器" tabindex="-1"><a class="header-anchor" href="#_4-输出解析器"><span>4. 输出解析器</span></a></h3><p>模型返回原始文本，你想让它返回结构化 JSON 时用 <code>StructuredOuputParser</code> / <code>JsonOutputParser</code>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatPromptTemplate <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/prompts&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> JsonOutputParser <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/output_parsers&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 让模型返回 JSON，这会指定 JSON schema</span></span>
<span class="line"><span class="token keyword">const</span> parser <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">JsonOutputParser</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span><span class="token function">fromMessages</span><span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;根据用户的问题，用 JSON 格式返回，字段为 answer 和 confidence。只返回 JSON。&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;human&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;{question}&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> chain <span class="token operator">=</span> prompt<span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>parser<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> chain<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span> question<span class="token operator">:</span> <span class="token string">&#39;1+1 等于几？&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>answer<span class="token punctuation">)</span>      <span class="token comment">// 2</span></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>confidence<span class="token punctuation">)</span>  <span class="token comment">// 1</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对前端来说，<code>JsonOutputParser</code> 就是自动帮你 <code>JSON.parse()</code> 的工具，还能拿到类型推断。</p><hr><h2 id="对话历史-memory" tabindex="-1"><a class="header-anchor" href="#对话历史-memory"><span>对话历史（Memory）</span></a></h2><p>默认情况模型不记得之前的对话，你需要手动把历史消息传回去。LangChain 提供 <strong><code>RunnableWithMessageHistory</code></strong> 帮你自动管理：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatPromptTemplate<span class="token punctuation">,</span> MessagesPlaceholder <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/prompts&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> RunnableWithMessageHistory <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/runnables&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> InMemoryChatMessageHistory <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/chats&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> HumanMessage <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/messages&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> prompt <span class="token operator">=</span> ChatPromptTemplate<span class="token punctuation">.</span><span class="token function">fromMessages</span><span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;你是一个友好的助手。&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token comment">// 历史消息插到这里，位置很重要</span></span>
<span class="line">  <span class="token keyword">new</span> <span class="token class-name">MessagesPlaceholder</span><span class="token punctuation">(</span><span class="token string">&#39;history&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">[</span><span class="token string">&#39;human&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;{input}&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> chain <span class="token operator">=</span> prompt<span class="token punctuation">.</span><span class="token function">pipe</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// storage：用一个 Map 以 sessionId 为 key 存每个用户的历史</span></span>
<span class="line"><span class="token keyword">const</span> messageHistories<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> InMemoryChatMessageHistory<span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> chainWithHistory <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">RunnableWithMessageHistory</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  runnable<span class="token operator">:</span> chain<span class="token punctuation">,</span></span>
<span class="line">  <span class="token function-variable function">getMessageHistory</span><span class="token operator">:</span> <span class="token keyword">async</span> <span class="token punctuation">(</span>sessionId<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>messageHistories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      messageHistories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">InMemoryChatMessageHistory</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> messageHistories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  inputMessagesKey<span class="token operator">:</span> <span class="token string">&#39;input&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  historyMessagesKey<span class="token operator">:</span> <span class="token string">&#39;history&#39;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第一次对话</span></span>
<span class="line"><span class="token keyword">const</span> res1 <span class="token operator">=</span> <span class="token keyword">await</span> chainWithHistory<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">{</span> input<span class="token operator">:</span> <span class="token string">&#39;我叫小明&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> configurable<span class="token operator">:</span> <span class="token punctuation">{</span> sessionId<span class="token operator">:</span> <span class="token string">&#39;user-001&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>res1<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 你好小明！很高兴认识你。</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 第二次对话，模型记得你</span></span>
<span class="line"><span class="token keyword">const</span> res2 <span class="token operator">=</span> <span class="token keyword">await</span> chainWithHistory<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">{</span> input<span class="token operator">:</span> <span class="token string">&#39;我叫什么名字？&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> configurable<span class="token operator">:</span> <span class="token punctuation">{</span> sessionId<span class="token operator">:</span> <span class="token string">&#39;user-001&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>res2<span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 你叫小明。</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>sessionId</code> 就像前端里的 <code>localStorage key</code>，每个用户用自己的 ID，互不干扰就能各自记对话。</p><hr><h2 id="工具-tool" tabindex="-1"><a class="header-anchor" href="#工具-tool"><span>工具（Tool）</span></a></h2><p>让模型能调用你的外部功能，比如查天气、查订单、调你自己的 API：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> tool <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/tools&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> z <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;zod&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 定义一个天气工具：用 z.infer 定义入参类型，类型即文档</span></span>
<span class="line"><span class="token keyword">const</span> weatherTool <span class="token operator">=</span> <span class="token function">tool</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> city <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> data<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">string</span><span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token string-property property">&#39;北京&#39;</span><span class="token operator">:</span> <span class="token string">&#39;晴天，25°C&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token string-property property">&#39;上海&#39;</span><span class="token operator">:</span> <span class="token string">&#39;多云，28°C&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token string-property property">&#39;深圳&#39;</span><span class="token operator">:</span> <span class="token string">&#39;雨天，26°C&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token comment">// 实际项目这里调用天气 API</span></span>
<span class="line">    <span class="token keyword">return</span> data<span class="token punctuation">[</span>city<span class="token punctuation">]</span> <span class="token operator">??</span> <span class="token string">&#39;暂无数据&#39;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span></span>
<span class="line">    name<span class="token operator">:</span> <span class="token string">&#39;get_weather&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    description<span class="token operator">:</span> <span class="token string">&#39;查询指定城市的天气&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    schema<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      city<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token string">&#39;城市名&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>细节点：<code>zod</code> 定义入参 schema 后，LangChain 会自动把 <code>schema</code> 翻译成模型的 function calling 参数，也保证类型安全。</p></blockquote><hr><h2 id="agent-智能体" tabindex="-1"><a class="header-anchor" href="#agent-智能体"><span>Agent（智能体）</span></a></h2><p>Agent 让模型<strong>自己决定</strong>调哪个工具、按什么顺序。这是最强大的能力：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> tool <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/tools&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> z <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;zod&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> createReactAgent <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/langgraph/prebuilt&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> weatherTool <span class="token operator">=</span> <span class="token function">tool</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span>  <span class="token comment">// 复用上面的工具</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> agent <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">createReactAgent</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  llm<span class="token operator">:</span> model<span class="token punctuation">,</span></span>
<span class="line">  tools<span class="token operator">:</span> <span class="token punctuation">[</span>weatherTool<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 直接调用，Agent 会自动判断是否要调用工具</span></span>
<span class="line"><span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> agent<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span> messages<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> role<span class="token operator">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> content<span class="token operator">:</span> <span class="token string">&#39;北京今天天气怎么样？&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>messages<span class="token punctuation">[</span>result<span class="token punctuation">.</span>messages<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">.</span>content<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 北京今天天气是晴天，25°C。</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行过程：</p><ol><li>用户问「北京天气」</li><li>Agent 分析后决定调用 <code>get_weather({ city: &#39;北京&#39; })</code></li><li>拿到结果后，Agent 组织成自然语言回复</li></ol><blockquote><p>早期 LangChain.js 用 <code>createToolCallingAgent</code> + <code>AgentExecutor</code>，新版更推荐 <code>@langchain/langgraph</code> 的 <code>createReactAgent</code>。两者都能跑，React Agent 更贴近现代写法。</p></blockquote><hr><h2 id="实战-做一个-ai-客服" tabindex="-1"><a class="header-anchor" href="#实战-做一个-ai-客服"><span>实战：做一个 AI 客服</span></a></h2><p>把前面学的都拼起来——工具 + 记忆 + Agent：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token keyword">import</span> <span class="token string">&#39;dotenv/config&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> ChatOpenAI <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/openai&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> tool <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/tools&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> z <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;zod&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> createReactAgent <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/langgraph/prebuilt&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> InMemoryChatMessageHistory <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/chats_helpers&#39;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> HumanMessage<span class="token punctuation">,</span> AIMessage <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@langchain/core/messages&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> model <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ChatOpenAI</span><span class="token punctuation">(</span><span class="token punctuation">{</span> model<span class="token operator">:</span> <span class="token string">&#39;gpt-4o-mini&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 1. 定义工具</span></span>
<span class="line"><span class="token keyword">const</span> checkOrder <span class="token operator">=</span> <span class="token function">tool</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> orderId <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">订单 </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>orderId<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> 已发货，预计 3 天内到达</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token string">&#39;check_order&#39;</span><span class="token punctuation">,</span> description<span class="token operator">:</span> <span class="token string">&#39;查询订单状态&#39;</span><span class="token punctuation">,</span> schema<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span> orderId<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> getProductInfo <span class="token operator">=</span> <span class="token function">tool</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> productName <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>productName<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">，价格 99 元，库存 100 件</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token string">&#39;get_product_info&#39;</span><span class="token punctuation">,</span> description<span class="token operator">:</span> <span class="token string">&#39;查询商品信息&#39;</span><span class="token punctuation">,</span> schema<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">object</span><span class="token punctuation">(</span><span class="token punctuation">{</span> productName<span class="token operator">:</span> z<span class="token punctuation">.</span><span class="token function">string</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 2. 创建 Agent（先简单版，不带记忆）</span></span>
<span class="line"><span class="token keyword">const</span> agent <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">createReactAgent</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  llm<span class="token operator">:</span> model<span class="token punctuation">,</span></span>
<span class="line">  tools<span class="token operator">:</span> <span class="token punctuation">[</span>checkOrder<span class="token punctuation">,</span> getProductInfo<span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  prompt<span class="token operator">:</span> <span class="token string">&#39;你是一个电商客服助手，请用中文回答。&#39;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 3. 加记忆：每位用户各自的历史</span></span>
<span class="line"><span class="token keyword">const</span> histories<span class="token operator">:</span> Record<span class="token operator">&lt;</span><span class="token builtin">string</span><span class="token punctuation">,</span> InMemoryChatMessageHistory<span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">ask</span><span class="token punctuation">(</span>sessionId<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">,</span> message<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>histories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span><span class="token punctuation">)</span> histories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">InMemoryChatMessageHistory</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token keyword">await</span> agent<span class="token punctuation">.</span><span class="token function">invoke</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    messages<span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token operator">...</span><span class="token punctuation">(</span><span class="token keyword">await</span> histories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">getMessages</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token punctuation">{</span> role<span class="token operator">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> content<span class="token operator">:</span> message <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">const</span> reply <span class="token operator">=</span> state<span class="token punctuation">.</span>messages<span class="token punctuation">[</span>state<span class="token punctuation">.</span>messages<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">.</span>content <span class="token keyword">as</span> <span class="token builtin">string</span></span>
<span class="line">  <span class="token keyword">await</span> histories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">addMessage</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">HumanMessage</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">await</span> histories<span class="token punctuation">[</span>sessionId<span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">addMessage</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">AIMessage</span><span class="token punctuation">(</span>reply<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">return</span> reply</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">await</span> <span class="token function">ask</span><span class="token punctuation">(</span><span class="token string">&#39;u1&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;我的订单 12345 到哪了？&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">await</span> <span class="token function">ask</span><span class="token punctuation">(</span><span class="token string">&#39;u1&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;再帮我查一下 iPhone 的价格&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="langchain-js-生态" tabindex="-1"><a class="header-anchor" href="#langchain-js-生态"><span>LangChain.js 生态</span></a></h2><p>TS 版生态包名以 <code>@langchain/*</code> 开头：</p><table><thead><tr><th>包名</th><th>用途</th></tr></thead><tbody><tr><td><code>langchain</code></td><td>核心框架</td></tr><tr><td><code>@langchain/openai</code></td><td>OpenAI / 兼容接口模型接入</td></tr><tr><td><code>@langchain/anthropic</code></td><td>Claude 接入</td></tr><tr><td><code>@langchain/core</code></td><td>核心抽象（prompt、tool、message）</td></tr><tr><td><code>@langchain/langgraph</code></td><td>Agent 编排（推荐用它做 Agent）</td></tr><tr><td><code>@langchain/community</code></td><td>社区集成（向量数据库、工具等）</td></tr></tbody></table><hr><h2 id="和前端框架类比" tabindex="-1"><a class="header-anchor" href="#和前端框架类比"><span>和前端框架类比</span></a></h2><table><thead><tr><th>LangChain.js</th><th>React / Vue</th></tr></thead><tbody><tr><td>Prompt</td><td>组件模板（JSX）</td></tr><tr><td>Chain 组织</td><td>组件组合 / pipe</td></tr><tr><td>Tool</td><td>API 接口</td></tr><tr><td>Agent</td><td>智能路由 / 状态机</td></tr><tr><td>Memory</td><td>状态管理（Redux / Pinia）</td></tr><tr><td>RunnableWithMessageHistory</td><td>高阶组件（HOC）</td></tr><tr><td><code>.pipe()</code></td><td>函数组合 / pipeline</td></tr></tbody></table><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>LangChain.js 的开发模板，跟 Python 版一模一样五步：</p><ol><li>选模型 → <code>new ChatOpenAI()</code></li><li>写提示词 → <code>ChatPromptTemplate</code></li><li>串步骤 → <code>prompt.pipe(model).pipe(parser)</code></li><li>加功能 → <code>tool(...)</code></li><li>让模型自己决策 → <code>createReactAgent</code></li></ol><p>前端开发者上手 LangChain.js 有天然优势：你懂异步、懂 API、懂状态管理，把 LLM 当成一个「有点特别的后端 API」就好。</p><hr><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步"><span>下一步</span></a></h2><ul><li><a href="https://js.langchain.com/" target="_blank" rel="noopener noreferrer">LangChain.js 官方文档</a></li><li><a href="./langchain">Python 版教程</a></li><li><a href="https://smith.langchain.com/" target="_blank" rel="noopener noreferrer">LangSmith 调试平台</a></li></ul>`,81)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};